import numpy as np

def feature(item, bins, capacity):
    """Negated distance (in capacity units) between a bin's remaining room and twice the item, i.e. prefers bins that would leave a leftover exactly equal to the item (pairing fit)."""
    b = np.asarray(bins, dtype=float)
    c = float(capacity)
    if not np.isfinite(c) or c <= 0.0:
        c = 1.0
    v = np.abs(2.0 * float(item) - b) / c
    return np.clip(-v, -1.0, 0.0)

import numpy as np

def feature(item, bins, capacity):
    """Negative absolute deviation of a bin's leftover after placing the item from the median leftover over all candidates, scaled by capacity (0 = typical bin, -1 = extreme bin)."""
    r = (np.asarray(bins, dtype=float) - float(item)) / float(capacity)
    m = float(np.median(r))
    return np.clip(-np.abs(r - m), -1.0, 1.0)

import numpy as np

def feature(item, bins, capacity):
    """Best-fit slack after placing the item, as leftover room over capacity (clipped to [0,1]), plus a sharp 'this bin is now closed' knee exp(-slack/0.1); two columns per candidate."""
    slack = np.clip((bins - item) / capacity, 0.0, 1.0)
    closed = np.exp(-slack / 0.1)
    return np.column_stack((slack, closed))

import numpy as np

def feature(item, bins, capacity):
    """Recency rank of each candidate: 0 for the oldest open bin, 1 for the brand-new bin (a smooth, graded version of the empty-bin flag)."""
    k = len(bins)
    if k <= 1:
        # only the brand-new bin is a candidate: forced choice
        return np.ones(k, dtype=float)
    return np.arange(k, dtype=float) / (k - 1.0)

import numpy as np

def feature(item, bins, capacity):
    """Candidate's position in the oldest-first list (0 = oldest open bin, 1 = brand-new bin) and its product with the post-placement residual room, giving a first-fit/consolidation bias whose ranking is not monotone in remaining room."""
    b = np.asarray(bins, dtype=float)
    k = b.size
    cap = float(capacity)
    it = float(item)
    if k <= 1:
        return np.zeros((k, 2), dtype=float)
    # age signal: -1 for the oldest open bin ... +1 for the brand-new bin (always last)
    age = np.clip(2.0 * np.arange(k, dtype=float) / (k - 1) - 1.0, -1.0, 1.0)
    resid = np.clip((b - it) / cap, -1.0, 1.0)
    return np.column_stack([age, age * resid])

import numpy as np

def feature(item, bins, capacity):
    """New-bin marker signed by the scarcity of open bins that can still take the item: positive when no open bin fits, negative when every open bin fits."""
    b = np.asarray(bins, dtype=float)
    cap = float(capacity)
    it = float(item)
    if b.size <= 1:
        frac_fit = 0.0
    else:
        frac_fit = float(np.mean(b[:-1] >= it - 1e-9))
    is_new = (b >= cap - 1e-9).astype(float)
    scarcity = 1.0 - 2.0 * frac_fit  # +1: nothing fits, -1: everything fits
    return np.clip(is_new * scarcity, -1.0, 1.0)

import numpy as np

def feature(item, bins, capacity):
    """Isolation of a candidate's post-placement leftover: the smallest gap to any other candidate's leftover, over capacity (0 when alone)."""
    cap = float(capacity)
    b = np.asarray(bins, dtype=float)
    L = (b - float(item)) / cap          # post-placement leftover per candidate, in capacity units
    k = L.shape[0]
    if k < 2:
        return np.zeros(k)
    diff = np.abs(L[:, None] - L[None, :])  # pairwise distances between leftovers
    np.fill_diagonal(diff, np.inf)          # ignore self
    return np.clip(diff.min(axis=1), 0.0, 1.0)

import numpy as np

def feature(item, bins, capacity):
    """Age-weighted sqrt fit quality: clip(age * sqrt(1 - clip((bins - item)/capacity, 0, 1)), -1, 1), new bin age 0."""
    k = len(bins)
    if k < 2:
        return np.zeros(k, dtype=float)
    idx = np.arange(k, dtype=float)
    age = 1.0 - idx / (k - 1)
    age[-1] = 0.0
    slack = np.clip((bins - item) / max(float(capacity), 1e-9), 0.0, 1.0)
    fitq = np.sqrt(1.0 - slack)
    return np.clip(age * fitq, -1.0, 1.0)

import numpy as np

def feature(item, bins, capacity):
    """Affinity of a candidate's remaining room to the typical (mean) remaining room of the open bins: peaks for representative bins, falls off for outliers (balanced fill)."""
    b = np.asarray(bins, dtype=float)
    cap = float(capacity)
    n_open = b.shape[0] - 1  # last entry is the brand-new empty bin
    if n_open <= 0:
        # only the new bin exists: no signal to give
        return np.zeros(b.shape[0])
    m = float(np.mean(b[:n_open]))
    # inverted V (peak at b == m, slope 2/cap, bounded by [-1, 1])
    v = 1.0 - 2.0 * np.abs(b - m) / cap
    return np.clip(v, -1.0, 1.0)

import numpy as np

def feature(item, bins, capacity):
    """Candidate age (normalised position among open bins, 0 = oldest, 1 = brand-new) and its interaction with post-placement slack, so the policy can prefer filling old bins whose leftover still leaves room."""
    cap = float(capacity)
    b = np.asarray(bins, dtype=float)
    k = b.shape[0]
    if k <= 1:
        age = np.zeros(k, dtype=float)
    else:
        age = np.arange(k, dtype=float) / float(k - 1)
    slack = np.clip((b - float(item)) / cap, 0.0, 1.0)
    return np.column_stack([age, age * slack])
